function miniShell(active,content,role='consumer'){const nav=roleMiniNav[role]||miniNav.map(([id,t])=>[id,t,'consumer',id,({'home':'⌂','consumer-recommendations':'☆','consumer-stores':'▦','consumer-orders':'▤','consumer-profile':'●'}[id])]);return '<div class="mini-app mini-role-'+e(role)+'"><header class="mini-top"><b>邻里生活</b><small>'+e(role==='merchant'?'商家服务':role==='admission'?'商家入驻':'社区服务')+'</small></header>'+content+'<nav class="mini-tabbar">'+nav.map(([id,t,toRole,toId,icon])=>'<a class="'+((active===id||active===toId)?'active':'')+'" href="'+href(toRole,toId,toRole==='admission'?'edit':'list')+'"><span aria-hidden="true">'+icon+'</span>'+t+'</a>').join('')+'</nav></div>';}
