function consumerProfile(){return miniShell('consumer-profile','<main class="mini-content"><div class="profile-hero"><span class="avatar">我</span><div><h1>个人中心</h1><p>账户资料与商家服务</p></div></div><section class="profile-group"><h2>账户资料</h2><a href="'+href('consumer','consumer-profile','edit')+'">个人资料　›</a><a href="'+href('consumer','consumer-orders')+'">我的订单　›</a></section><section class="profile-group"><h2>商家中心</h2><a class="profile-primary" href="'+href('admission')+'">商家入驻 / 查看入驻进度 <b>›</b></a><a href="'+href('merchant')+'">商家工作台（按原权限）　›</a><p>联系客服：当前项目未发现可复用入口，暂不可用。</p></section><section class="profile-group"><h2>其他原有服务</h2>'+data.pages.filter(p=>p.role==='consumer'&&!['consumer-home','consumer-stores','consumer-orders','consumer-profile','consumer-basket'].includes(p.id)).map(p=>link(p.title+'　›',href('consumer',p.id),'')).join('')+'</section><p class="mini-disclaimer">未执行微信授权；商家入驻、微信支付、支付可用与分账可用是不同状态。获得merchantID不代表支付已开通；本地草稿不代表官方申请状态。</p></main>');}
