function consumerReferrals(){const d=state.referralDraft||{code:''};return miniShell('consumer-referrals','<main class="mini-content"><p class="mini-kicker">推荐与归属 · 原客户中心字段投影</p><h1>推荐关系</h1><section class="profile-group"><h2>我的推荐码</h2><p>演示推荐码：<strong>REF-DEMO-001</strong></p><p class="mini-disclaimer">合成展示值，不是可用邀请凭证，不会创建推荐关系。</p></section><section class="profile-group"><h2>绑定推荐人</h2><label for="referral-code">推荐码（仅演示输入）</label><input id="referral-code" data-referral-code maxlength="64" value="'+e(d.code)+'" autocomplete="off" placeholder="输入合成示例码"><button type="button" id="referral-preview">检查示例</button><p id="referral-preview-status" role="status">未检查；不会真实绑定或更改既有关系。</p></section><section class="profile-group"><h2>推荐人关系</h2><p>当前示例状态：未读取真实关系。</p><p>真实规则（他人绑定、旧绑定不可变、防止自绑定/循环）由原客户中心处理；本页面不实现绑定算法或佣金/奖励。</p></section><div class="actions">'+link('返回首页',href('consumer','home'),'button secondary')+link('个人中心',href('consumer','consumer-profile'),'button secondary')+'</div></main>');}

